const CACHE_NAME = 'clientify-v1';
const ASSETS = [
  '/',
  '/index.html',
  '/manifest.json',
  '/index.tsx',
  '/App.tsx',
  '/types.ts',
  '/constants.ts'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS);
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.filter(key => key !== CACHE_NAME).map(key => caches.delete(key))
      );
    })
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // API calls: Network-first
  if (url.pathname.includes('/api/') || url.pathname.includes('/auth/')) {
    event.respondWith(
      fetch(event.request)
        .then((response) => {
          const resClone = response.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, resClone));
          return response;
        })
        .catch(() => caches.match(event.request))
    );
    return;
  }

  // Assets and esm.sh modules: Stale-while-revalidate
  event.respondWith(
    caches.match(event.request).then((cached) => {
      const networked = fetch(event.request)
        .then((response) => {
          const resClone = response.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, resClone));
          return response;
        })
        .catch(() => null);
      return cached || networked;
    })
  );
});

import React, { useState, useEffect, useCallback } from 'react';
import { AuthProvider, useAuth } from './auth/AuthContext.tsx';
import ProtectedRoute from './components/ProtectedRoute.tsx';
import Navbar from './components/Navbar.tsx';
import Home from './pages/Home.tsx';
import Dashboard from './pages/Primary/Dashboard.tsx';
import Login from './auth/Login.tsx';
import Signup from './auth/Signup.tsx';
import Loader from './components/Loader.tsx';
import OfflineBanner from './components/OfflineBanner.tsx';
import { api } from './services/api.ts';
import { useOffline } from './hooks/useOffline.ts';

type Page = 'home' | 'login' | 'signup' | 'dashboard';

const AppContent: React.FC = () => {
  const { isAuthenticated, token, hasCheckedAuth, isLoading } = useAuth();
  const [currentPage, setCurrentPage] = useState<Page>('home');

  const handleReconnect = useCallback(() => {
    if (token) {
      api.get('/auth/me').catch(console.error);
    }
  }, [token]);

  const isOnline = useOffline(handleReconnect);

  useEffect(() => {
    if (!hasCheckedAuth) return;
    if (isAuthenticated) {
      setCurrentPage('dashboard');
    } else if (currentPage === 'dashboard') {
      setCurrentPage('home');
    }
  }, [isAuthenticated, hasCheckedAuth]);

  if (!hasCheckedAuth) return <Loader />;

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return (
          <>
            <Navbar onLoginClick={() => setCurrentPage('login')} onHomeClick={() => setCurrentPage('home')} />
            <Home onGetStarted={() => setCurrentPage('signup')} />
          </>
        );
      case 'login':
        return <Login onSwitch={() => setCurrentPage('signup')} onBackToHome={() => setCurrentPage('home')} />;
      case 'signup':
        return <Signup onSwitch={() => setCurrentPage('login')} onBackToHome={() => setCurrentPage('home')} />;
      case 'dashboard':
        return (
          <ProtectedRoute fallback={<Login onSwitch={() => setCurrentPage('signup')} onBackToHome={() => setCurrentPage('home')} />}>
            <Dashboard />
          </ProtectedRoute>
        );
      default:
        return <Home onGetStarted={() => setCurrentPage('signup')} />;
    }
  };

  return (
    <>
      <OfflineBanner isOnline={isOnline} />
      {renderPage()}
      {isLoading && <div className="fixed inset-0 z-[9999] bg-slate-950/20 backdrop-blur-sm"><Loader /></div>}
    </>
  );
};

const App: React.FC = () => (
  <AuthProvider>
    <AppContent />
  </AuthProvider>
);

export default App;

import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import { User } from '../types.ts';
import { api } from '../services/api.ts';

interface AuthContextType {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  login: (user_id: string, password: string) => Promise<void>;
  signup: (data: any) => Promise<void>;
  logout: () => void;
  isLoading: boolean;
  hasCheckedAuth: boolean;
  error: string | null;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Cookie Helpers
const setCookie = (name: string, value: string, days: number) => {
  const expires = new Date(Date.now() + days * 864e5).toUTCString();
  document.cookie = `${name}=${encodeURIComponent(value)}; expires=${expires}; path=/; SameSite=Lax; Secure`;
};

const getCookie = (name: string) => {
  const cookies = document.cookie.split('; ');
  for (let i = 0; i < cookies.length; i++) {
    const parts = cookies[i].split('=');
    if (parts[0] === name) return decodeURIComponent(parts[1]);
  }
  return '';
};

const deleteCookie = (name: string) => {
  document.cookie = `${name}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;`;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasCheckedAuth, setHasCheckedAuth] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Initialize: Check for existing session on reload
  useEffect(() => {
    const initAuth = async () => {
      try {
        const savedToken = getCookie('clientify_token');
        if (savedToken) {
          setIsLoading(true);
          api.setToken(savedToken);
          const response = await api.get('/auth/me');
          if (response && response.user) {
            setToken(savedToken);
            setUser(response.user);
          } else {
            throw new Error('Invalid user session');
          }
        }
      } catch (err) {
        console.warn('Auth check skipped or failed:', err);
        deleteCookie('clientify_token');
        api.setToken(null);
      } finally {
        setIsLoading(false);
        setHasCheckedAuth(true);
      }
    };
    initAuth();
  }, []);

  const login = async (user_id: string, password: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await api.post('/auth/login', { user_id, password });
      setToken(response.token);
      setUser(response.user);
      setCookie('clientify_token', response.token, 7);
      api.setToken(response.token);
    } catch (err: any) {
      const msg = err.message || 'Login failed';
      setError(msg);
      throw new Error(msg);
    } finally {
      setIsLoading(false);
    }
  };

  const signup = async (data: any) => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await api.post('/auth/signup', data);
      setToken(response.token);
      setUser(response.user);
      setCookie('clientify_token', response.token, 7);
      api.setToken(response.token);
    } catch (err: any) {
      const msg = err.message || 'Signup failed';
      setError(msg);
      throw new Error(msg);
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    setUser(null);
    setToken(null);
    setError(null);
    deleteCookie('clientify_token');
    api.setToken(null);
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      token, 
      isAuthenticated: !!token, 
      login, 
      signup, 
      logout, 
      isLoading, 
      hasCheckedAuth,
      error 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import { API_BASE_URL } from '../constants.ts';
import { mockBackend } from './mockBackend.ts';

class ApiService {
  private token: string | null = null;
  private minDelay = 1200; 
  public isMockMode = false;

  setToken(token: string | null) {
    this.token = token;
  }

  private getFullUrl(endpoint: string): string {
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    return `${API_BASE_URL}/api${cleanEndpoint}`;
  }

  private async withMinDelay<T>(task: Promise<T>): Promise<T> {
    const start = Date.now();
    try {
      const result = await task;
      const elapsed = Date.now() - start;
      if (elapsed < this.minDelay) {
        await new Promise(resolve => setTimeout(resolve, this.minDelay - elapsed));
      }
      return result;
    } catch (error) {
      const elapsed = Date.now() - start;
      if (elapsed < this.minDelay) {
        await new Promise(resolve => setTimeout(resolve, this.minDelay - elapsed));
      }
      throw error;
    }
  }

  async get(endpoint: string) {
    if (!API_BASE_URL || this.isMockMode) {
      this.isMockMode = true;
      return this.withMinDelay(this.handleMockRequest('GET', endpoint));
    }

    try {
      const headers: HeadersInit = this.token ? { 'Authorization': `Bearer ${this.token}` } : {};
      const res = await fetch(this.getFullUrl(endpoint), { method: 'GET', headers });
      return this.withMinDelay(this.handleResponse(res));
    } catch (err) {
      this.isMockMode = true;
      return this.get(endpoint);
    }
  }

  async post(endpoint: string, data: any) {
    if (!API_BASE_URL || this.isMockMode) {
      this.isMockMode = true;
      return this.withMinDelay(this.handleMockRequest('POST', endpoint, data));
    }

    try {
      const headers: HeadersInit = {
        'Content-Type': 'application/json',
        ...(this.token ? { 'Authorization': `Bearer ${this.token}` } : {})
      };
      const res = await fetch(this.getFullUrl(endpoint), {
        method: 'POST',
        headers,
        body: JSON.stringify(data),
      });
      return this.withMinDelay(this.handleResponse(res));
    } catch (err) {
      this.isMockMode = true;
      return this.post(endpoint, data);
    }
  }

  private async handleMockRequest(method: string, endpoint: string, data?: any) {
    if (endpoint === '/auth/me' && this.token) return mockBackend.me(this.token);
    if (endpoint === '/auth/login') {
      const res = await mockBackend.login(data.user_id, data.password);
      this.token = res.token;
      return res;
    }
    if (endpoint === '/auth/signup') {
      const res = await mockBackend.signup(data);
      this.token = res.token;
      return res;
    }
    if (endpoint === '/items') {
      const userId = this.token?.replace('mock_token_', '') || 'guest';
      if (method === 'GET') return mockBackend.getItems(userId);
      if (method === 'POST') return mockBackend.createItem(userId, data);
    }
    return {};
  }

  private async handleResponse(response: Response) {
    const responseText = await response.text();
    let result;
    try {
      result = responseText ? JSON.parse(responseText) : {};
    } catch (e) {
      throw new Error(`Invalid server response (${response.status})`);
    }
    if (!response.ok) throw new Error(result.message || result.error || 'Request failed');
    return result;
  }
}

export const api = new ApiService();

