const VIEW_CONFIG: Record<string, { label: string; description: string }> = {
  'dashboard': { label: 'Firm Overview', description: 'Real-time practice performance metrics.' },
  'gst-portfolio': { label: 'GST Master List', description: 'Central client repository for GST Portal identifiers.' },
  'it-portfolio': { label: 'IT Master List', description: 'Income Tax identifier vault for legal entities.' },
  'compliance-monthly': { label: 'Monthly Filing', description: 'GSTR-1 and GSTR-3B status for regular taxpayers.' },
  'compliance-quarterly': { label: 'Quarterly Filing', description: 'QRMP scheme tracking for regular taxpayers.' },
  'compliance-composition': { label: 'Composition Filing', description: 'CMP-08 tracking for composition dealers.' },
  'compliance-gstr4': { label: 'GSTR-4 Annual', description: 'Annual statutory return for composition dealers.' },
  'compliance-gstr9': { label: 'GSTR-9 & 9C', description: 'Annual audit returns for regular taxpayers.' },
  'compliance-itr': { label: 'ITR Returns', description: 'Direct tax return tracking for all individuals and firms.' },
  'compliance-taxaudit': { label: 'Audit & B/S', description: 'Financial statement finalization and audit reporting.' },
  'lit-notice-pending': { label: 'Pending Notices', description: 'Live tracking of show cause notices awaiting response.' },
  'reminders': { label: 'Reminders', description: 'Statutory deadline tracker for the current month.' },
  'admin-invoices': { label: 'Invoice Hub', description: 'Professional fee billing and payment tracking.' },
  'settings': { label: 'Profile Settings', description: 'Manage firm identity and vault security.' }
};

const Dashboard: React.FC = () => {
  const { user, token } = useAuth();
  const isOnline = useOffline();
  const { installPrompt, triggerInstall } = usePWA();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDataLoading, setIsDataLoading] = useState(false);
  const [activeView, setActiveView] = useState<ActiveView>('dashboard');
  const [viewExtra, setViewExtra] = useState<any>(null);

  const [metrics, setMetrics] = useState<MetricData[]>(INITIAL_METRICS);

  const activeViewConfig = useMemo(() => VIEW_CONFIG[activeView] || { label: 'Practice Suite', description: 'Professional Vault Solution' }, [activeView]);

  const handleViewChange = (view: ActiveView, extra?: any) => {
    setActiveView(view);
    setViewExtra(extra || null);
  };

  const loadMetrics = useCallback(async () => {
    if (!token) return;
    setIsDataLoading(true);
    try {
      const [clients, litigation, invoices, miscWork] = await Promise.all([
        api.getClients(),
        api.getLitigationRecords(),
        api.getInvoices(),
        api.getMiscWork()
      ]);

      setMetrics([
        { label: 'Active Clients', value: clients.length, trend: 'stable' },
        { label: 'Pending Litigation', value: litigation.filter(l => l.status === 'Pending').length, trend: 'up' },
        { label: 'Open Invoices', value: invoices.filter(i => i.status !== 'Paid').length, trend: 'up' },
        { label: 'Pipeline Tasks', value: miscWork.filter(w => w.status !== 'Completed').length, trend: 'stable' },
      ]);
    } catch (err) {
      console.error('Vault Sync Error:', err);
    } finally {
      setIsDataLoading(false);
    }
  }, [token]);

  useEffect(() => {
    if (isOnline && token) loadMetrics();
  }, [isOnline, token, activeView, loadMetrics]);

  if (isDataLoading && activeView === 'dashboard') return <Loader />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="max-w-7xl mx-auto space-y-10 animate-in fade-in duration-500 overflow-y-auto h-full pr-1 no-scrollbar">
            {installPrompt && <InstallBanner onInstall={triggerInstall} />}
            <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 lg:grid-cols-4">
              {metrics.map((m, i) => <MetricCard key={i} metric={m} />)}
            </div>
            <div className="grid grid-cols-1 gap-8">
              <div className="rounded-[2.5rem] bg-white p-12 border border-slate-200 shadow-sm relative overflow-hidden">
                <div className="flex items-center justify-between mb-10">
                   <div>
                      <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tight">Performance Matrix</h3>
                      <p className="text-slate-500">Practice-wide compliance and billing overview.</p>
                   </div>
                   <button onClick={loadMetrics} className="px-6 h-12 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-black uppercase tracking-widest text-indigo-600 hover:bg-white hover:shadow-sm transition-all">Force Global Sync</button>
                </div>
                <div className="h-96 flex items-end justify-between gap-6 relative">
                  {[40, 70, 45, 90, 65, 85, 30, 95, 50, 75, 60, 80].map((h, i) => (
                    <div key={i} className="flex-1 bg-indigo-50 rounded-2xl group relative hover:bg-indigo-100 cursor-pointer transition-colors">
                      <div className="absolute inset-x-0 bottom-0 bg-indigo-600 rounded-2xl transition-all duration-700" style={{ height: `${h}%` }} />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );
      case 'gst-portfolio': return <GSTPortfolio />;
      case 'it-portfolio': return <ITPortfolio />;
      case 'compliance-monthly': return <MonthlyFiling />;
      case 'compliance-quarterly': return <QuarterlyFiling />;
      case 'compliance-composition': return <CompositionFiling />;
      case 'compliance-gstr4': return <GSTR4 />;
      case 'compliance-gstr9': return <GSTR9_9C />;
      case 'compliance-itr': return <ITRReturn />;
      case 'compliance-taxaudit': return <TAXAudit />;
      case 'lit-notice-pending': return <NoticePending />;
      case 'lit-notice-filed': return <NoticeFiled />;
      case 'lit-notice-drop': return <NoticeDrop />;
      case 'lit-notice-demand': return <NoticeDemand />;
      case 'lit-appeal-pending': return <AppealPending />;
      case 'lit-appeal-filed': return <AppealFiled />;
      case 'lit-appeal-drop': return <AppealDrop />;
      case 'lit-appeal-demand': return <AppealDemand />;
      case 'lit-tribunal-pending': return <TribunalPending />;
      case 'lit-tribunal-filed': return <TribunalFiled />;
      case 'lit-tribunal-drop': return <TribunalDrop />;
      case 'lit-tribunal-demand': return <TribunalDemand />;
      case 'lit-hc-pending': return <CourtPending />;
      case 'lit-hc-filed': return <CourtFiled />;
      case 'lit-hc-drop': return <CourtDrop />;
      case 'lit-hc-demand': return <CourtDemand />;
      case 'misc-gst-reg': return <GSTRegistration />;
      case 'misc-food-lic': return <FoodLicenses />;
      case 'misc-msme': return <MSMERegistration />;
      case 'misc-work': return <Miscellaneouswork />;
      case 'reminders': return <Reminders />;
      case 'messenger': return <Messenger />;
      case 'admin-invoices': return <Invoices onViewChange={handleViewChange} />;
      case 'admin-add-invoice': return <AddInvoice onBack={() => handleViewChange('admin-invoices')} editingInvoice={viewExtra} />;
      case 'admin-invoice-setting': return <InvoiceSetting onBack={() => handleViewChange('admin-invoices')} />;
      case 'admin-payments': return <PaymentReceived onViewChange={handleViewChange} />;
      case 'admin-duedates': return <DueDateSetting />;
      case 'settings': return <Setting />;
      case 'trash': return <Trash />;
      default: return <div className="p-20 text-center"><h2 className="text-2xl font-black text-slate-300 uppercase tracking-widest">Select Module from Sidebar</h2></div>;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-50">
      <Sidebar activeView={activeView} onViewChange={handleViewChange} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />
      <main className="flex flex-1 flex-col overflow-hidden relative">
        <Header isConnected={isOnline} currentUser={user} onMenuClick={() => setIsSidebarOpen(true)} activeViewLabel={activeViewConfig.label} activeViewDescription={activeViewConfig.description} />
        <div className="flex-1 flex flex-col min-h-0 px-6 lg:px-12 pt-3 pb-6 lg:pb-12">
          <Suspense fallback={<Loader />}>{renderView()}</Suspense>
        </div>
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Client, GSTProfile, ConstitutionType, GstStatus, GstRegType, GstFilingFreq, ClientStatus, JurisdictionType } from '../../types.ts';
import { api } from '../../services/api.ts';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<'basic' | 'portal' | 'office'>('basic');

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    tradeName: '',
    email: '',
    mobile: '',
    status: 'Active Filing',
    gstProfile: {
      gstin: '', pan: '', username: '', password: '', gstStatus: 'Active',
      regDate: '', regType: 'Regular', filingFreq: 'Monthly',
      constitution: 'Proprietorship', stakeholders: [],
      accountantName: '', accountantMobile: '', address: '',
      jurisdictionType: 'State', sector: '', range: ''
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        legalName: '', tradeName: '', email: '', mobile: '', status: 'Active Filing',
        gstProfile: {
          gstin: '', pan: '', username: '', password: '', gstStatus: 'Active',
          regDate: '', regType: 'Regular', filingFreq: 'Monthly',
          constitution: 'Proprietorship', stakeholders: [],
          accountantName: '', accountantMobile: '', address: '',
          jurisdictionType: 'State', sector: '', range: ''
        },
        bankDetails: { bankName: '', accountNo: '', ifsc: '' },
        remarks: ''
      });
    }
    setError(null);
    setActiveTab('basic');
  }, [initialData, isOpen]);

  const handleGstinChange = (val: string) => {
    const gstin = val.toUpperCase().slice(0, 15);
    let pan = formData.gstProfile?.pan || '';
    if (gstin.length >= 12) {
      pan = gstin.substring(2, 12);
    }
    setFormData(prev => ({
      ...prev,
      gstProfile: { ...prev.gstProfile!, gstin, pan }
    }));
  };

  const handleReturnLogic = (type: GstRegType) => {
    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        regType: type,
        filingFreq: type === 'Composition' ? 'Quarterly' : prev.gstProfile?.filingFreq || 'Monthly'
      }
    }));
  };

  const verifyGSTIN = () => {
    const gstin = formData.gstProfile?.gstin;
    if (!gstin) return;
    navigator.clipboard.writeText(gstin);
    window.open('https://services.gst.gov.in/services/searchtp', '_blank');
  };

  const handleSave = async () => {
    setError(null);
    setIsSaving(true);
    try {
      if (!formData.legalName) throw new Error("Legal Name is required");
      if (!formData.gstProfile?.gstin) throw new Error("GSTIN is required");

      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Sync Failed. Check network.");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 overflow-hidden">
      <div className="w-full max-w-4xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col max-h-[95vh] animate-in zoom-in-95">
        <div className="px-10 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50 shrink-0">
          <div className="flex items-center gap-4">
             <div className="h-12 w-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center shadow-lg">
                <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2-2h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011-1v5m-4 0h4" /></svg>
             </div>
             <div>
                <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase">GST Client Master</h2>
                <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mt-1">Live MongoDB Synchronization</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-slate-200 rounded-xl transition-colors">
            <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
          </button>
        </div>

        <div className="flex border-b border-slate-100 bg-white shrink-0">
           {['basic', 'portal', 'office'].map((t) => (
             <button key={t} onClick={() => setActiveTab(t as any)} 
               className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 ${activeTab === t ? 'border-indigo-600 text-indigo-600 bg-indigo-50/30' : 'border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}>
               {t === 'basic' ? 'Identity' : t === 'portal' ? 'Filing Config' : 'Admin & Banking'}
             </button>
           ))}
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-12 no-scrollbar">
          {error && <div className="p-4 bg-red-50 text-red-600 rounded-xl font-bold border border-red-100">{error}</div>}

          {activeTab === 'basic' && (
            <div className="space-y-10 animate-in fade-in duration-300">
               <section className="space-y-6">
                <h3 className="text-[11px] font-black uppercase text-indigo-600 tracking-[0.25em] flex items-center gap-3">Business Profile <div className="h-px flex-1 bg-slate-100" /></h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Legal Name</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-bold uppercase outline-none focus:ring-4 focus:ring-indigo-50" value={formData.legalName} onChange={e => setFormData({...formData, legalName: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Trade Name</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-bold uppercase outline-none focus:ring-4 focus:ring-indigo-50" value={formData.tradeName} onChange={e => setFormData({...formData, tradeName: e.target.value})} />
                  </div>
                  <div className="relative">
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">GSTIN</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-black uppercase font-mono tracking-widest outline-none pr-12 focus:ring-4 focus:ring-indigo-50" placeholder="22AAAAA0000A1Z5" value={formData.gstProfile?.gstin} onChange={e => handleGstinChange(e.target.value)} />
                    <button type="button" onClick={verifyGSTIN} title="Open Portal" className="absolute right-4 top-[42px] h-8 w-8 text-indigo-600 hover:bg-white rounded-lg flex items-center justify-center transition-all shadow-sm">
                       <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </button>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">PAN</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-black uppercase font-mono tracking-widest outline-none" value={formData.gstProfile?.pan} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, pan: e.target.value.toUpperCase().slice(0, 10)}})} />
                  </div>
                </div>
              </section>
              <section className="space-y-6">
                <h3 className="text-[11px] font-black uppercase text-indigo-600 tracking-[0.25em] flex items-center gap-3">Contact Information <div className="h-px flex-1 bg-slate-100" /></h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Mobile No</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-bold outline-none" value={formData.mobile} onChange={e => setFormData({...formData, mobile: e.target.value})} />
                   </div>
                   <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Email</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-bold outline-none lowercase" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                   </div>
                </div>
              </section>
            </div>
          )}

          {activeTab === 'portal' && (
            <div className="space-y-10 animate-in fade-in duration-300">
               <section className="space-y-6">
                <h3 className="text-[11px] font-black uppercase text-indigo-600 tracking-[0.25em] flex items-center gap-3">Return Lifecycle <div className="h-px flex-1 bg-slate-100" /></h3>
