  // Fix: Added migrateToPayment method to handle invoice settlement and payment recording
  async migrateToPayment(invoiceId: string, paymentData: { date: string, mode: string, chequeNo?: string }): Promise<void> {
    const all = await this.get('/items');
    const invoiceItem = all.find((i: any) => i._id === invoiceId);
    if (!invoiceItem) throw new Error("Invoice record not found in vault");

    const invoice = this.transformItem(invoiceItem) as InvoiceRecord;

    // 1. Create Payment Record
    const paymentPayload = {
      name: 'payment',
      data: {
        clientId: invoice.clientId,
        clientName: invoice.clientName,
        invoiceNo: invoice.invoiceNo,
        invoiceDate: invoice.date,
        date: paymentData.date,
        amount: invoice.totalAmount,
        mode: paymentData.mode,
        chequeNo: paymentData.chequeNo,
        originalItems: invoice.items
      }
    };
    await this.post('/items', paymentPayload);

    // 2. Update Invoice status to Paid
    const updatedInvoice = { ...invoice, status: 'Paid' as const };
    const invoicePayload = { name: 'invoice', data: updatedInvoice };
    await this.put(`/items/${invoiceId}`, invoicePayload);
  }
}

