                           <span className={`text-[10px] font-black uppercase ${hDays < 0 ? 'text-red-500' : hDays <= 7 ? 'text-orange-500' : 'text-emerald-600'}`}>
                              {hDays < 0 ? `${Math.abs(hDays)} Overdue` : `${hDays} Days Left`}
