  const { installPrompt, triggerInstall } = usePWA();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDataLoading, setIsDataLoading] = useState(false);
  const [activeView, setActiveView] = useState<ActiveView>('dashboard');
  const [viewExtra, setViewExtra] = useState<any>(null);

  const [metrics, setMetrics] = useState<MetricData[]>(INITIAL_METRICS);

  const activeViewConfig = useMemo(() => VIEW_CONFIG[activeView] || { label: 'Vault Module', description: 'Secured Professional Data' }, [activeView]);

  const handleViewChange = (view: ActiveView, extra?: any) => {
    setActiveView(view);
    setViewExtra(extra || null);
    setIsSidebarOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const loadMetrics = useCallback(async () => {
    if (!token) return;
    setIsDataLoading(true);
    try {
      const [clients, litigation, invoices, miscWork] = await Promise.all([
        api.getClients(),
        api.getLitigationRecords(),
        api.getInvoices(),
        api.getMiscWork()
      ]);

      setMetrics([
        { label: 'Total Clients', value: clients.length, trend: 'stable' },
        { label: 'Active Litigation', value: litigation.filter(l => l.status === 'Pending').length, trend: 'up' },
        { label: 'Pending Bills', value: invoices.filter(i => i.status !== 'Paid').length, trend: 'up' },
        { label: 'Firm Workflow', value: miscWork.filter(w => w.status !== 'Completed').length, trend: 'stable' },
      ]);
    } catch (err) {
      console.error('Firm Metric Sync Error:', err);
    } finally {
      setIsDataLoading(false);
    }
  }, [token]);

