    const hasChildren = !!item.children?.length;
    if (hasChildren) {
      setExpandedFolders(prev => prev.includes(item.id) ? prev.filter(f => f !== item.id) : [...prev, item.id]);
    } else {
      onViewChange(item.id as ActiveView);
      onClose();
    }
  };

  const renderItem = (item: NavItem, level = 0) => {
    const isExpanded = expandedFolders.includes(item.id);
    const isActive = activeView === item.id || (item.children?.some(c => c.id === activeView));
    const hasChildren = !!item.children?.length;

    return (
      <div key={item.id} className="w-full">
        <button
          onClick={() => handleItemClick(item)}
          className={`group flex w-full items-center gap-3 rounded-xl px-4 py-2.5 text-sm font-bold transition-all ${
            activeView === item.id ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600 hover:bg-slate-50'
          } ${level > 0 ? 'ml-4' : ''}`}
        >
          {item.icon && (
            <svg className={`h-5 w-5 shrink-0 ${activeView === item.id ? 'text-indigo-600' : 'text-slate-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              {item.icon}
