          )}
        </button>
        {hasChildren && isExpanded && (
          <div className="mt-1 space-y-1">
            {item.children?.map(child => renderItem(child, level + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <>
      <div className={`fixed inset-0 z-[60] bg-slate-900/20 backdrop-blur-sm lg:hidden transition-opacity ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} onClick={onClose} />
      <aside className={`fixed inset-y-0 left-0 z-[70] flex flex-col border-r border-slate-200 bg-white transition-transform duration-300 w-72 lg:translate-x-0 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex h-20 items-center px-8 border-b border-slate-100 shrink-0">
           <div className="flex items-center gap-3">
             <div className="h-8 w-8 rounded-lg bg-indigo-600" />
             <span className="text-xl font-black text-slate-900 tracking-tight">Clientify</span>
           </div>
        </div>
        <nav className="flex-1 overflow-y-auto p-4 space-y-2 no-scrollbar">
          {navigation[0].items.map(item => renderItem(item))}
        </nav>
      </aside>
    </>
  );
};

