    username: user?.username || '',
    email_id: user?.email_id || '',
    firm_name: user?.firm_name || '',
    gstn: user?.gstn || '',
    mobile_no: user?.mobile_no || '',
    avatar: user?.avatar || null
  });

  const [securityData, setSecurityData] = useState({
    user_id: user?.user_id || '',
    newPassword: '',
    confirmPassword: ''
  });

  const [uiSettings, setUiSettings] = useState(() => {
    const saved = localStorage.getItem('clientify_ui_settings');
    return saved ? JSON.parse(saved) : { fontSize: 16, fontStyle: 'sans' };
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const restoreInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (message) {
      const timer = setTimeout(() => setMessage(null), 5000);
      return () => clearTimeout(timer);
    }
  }, [message]);

  const handleProfileSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      await api.updateProfile(profileData);
      setMessage({ type: 'success', text: 'Firm identity updated in cloud vault.' });
      window.location.reload();
    } catch (err: any) {
      setMessage({ type: 'error', text: err.message || 'Update failed.' });
    } finally { setIsLoading(false); }
  };

  const handleSecuritySave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (securityData.newPassword && securityData.newPassword !== securityData.confirmPassword) {
      return setMessage({ type: 'error', text: 'Passwords mismatch.' });
    }
    setIsLoading(true);
    try {
      const payload: any = { user_id: securityData.user_id };
      if (securityData.newPassword) payload.password = securityData.newPassword;
      await api.updateProfile(payload);
      setMessage({ type: 'success', text: 'Access keys rotated successfully.' });
      setSecurityData({ ...securityData, newPassword: '', confirmPassword: '' });
    } catch (err: any) {
      setMessage({ type: 'error', text: err.message || 'Security update failed.' });
    } finally { setIsLoading(false); }
  };

  const applyUiSettings = (next: any) => {
    setUiSettings(next);
    localStorage.setItem('clientify_ui_settings', JSON.stringify(next));
    document.documentElement.style.setProperty('--ui-font-size', next.fontSize + 'px');
    document.body.classList.remove('app-font-sans', 'app-font-serif', 'app-font-mono');
    document.body.classList.add('app-font-' + next.fontStyle);
  };

  const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setProfileData({ ...profileData, avatar: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const triggerBackup = async () => {
    try {
      const dataStr = await api.backupAllData();
      const blob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `Vault_Backup_${new Date().toISOString().split('T')[0]}.json`;
      link.click();
      setMessage({ type: 'success', text: 'Vault Snapshot downloaded.' });
    } catch (err) { setMessage({ type: 'error', text: 'Backup failed.' }); }
  };

  const handleRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      try {
        const items = JSON.parse(ev.target?.result as string);
        if (confirm(`Inject ${items.length} records into current vault?`)) {
          setIsLoading(true);
          await api.restoreData(items);
          setMessage({ type: 'success', text: 'Data restoration sequence finished.' });
        }
      } catch (err) { setMessage({ type: 'error', text: 'Invalid backup file.' }); }
      finally { setIsLoading(false); if (restoreInputRef.current) restoreInputRef.current.value = ''; }
    };
    reader.readAsText(file);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm gap-1 overflow-x-auto no-scrollbar">
         {[
           { id: 'firm', label: 'Firm Detail' },
           { id: 'security', label: 'Vault Access' },
           { id: 'appearance', label: 'UI Style' },
           { id: 'data', label: 'Backup & Restore' }
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveTab(tab.id as any)}
             className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>
             {tab.label}
           </button>
         ))}
      </div>

      {message && (
        <div className={`p-4 rounded-xl text-center text-[10px] font-black uppercase tracking-widest border animate-in slide-in-from-top-4 ${message.type === 'success' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-red-50 text-red-600 border-red-100'}`}>
          {message.text}
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm p-10">
         {activeTab === 'firm' && (
           <form onSubmit={handleProfileSave} className="space-y-10 animate-in slide-in-from-bottom-4 duration-300">
              <div className="flex items-center gap-8 pb-10 border-b border-slate-100">
                 <div className="relative">
                    <div className="h-24 w-24 rounded-[1.5rem] bg-slate-100 overflow-hidden border-4 border-white shadow-xl">
                       {profileData.avatar ? <img src={profileData.avatar} className="h-full w-full object-cover" /> : <div className="h-full w-full flex items-center justify-center text-3xl font-black text-slate-300">{user?.username?.[0]}</div>}
                    </div>
                    <button type="button" onClick={() => fileInputRef.current?.click()} className="absolute -bottom-2 -right-2 h-8 w-8 bg-indigo-600 text-white rounded-lg flex items-center justify-center shadow-lg hover:scale-110 transition-all">
                       <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
                    </button>
                    <input type="file" ref={fileInputRef} onChange={handleAvatarChange} className="hidden" accept="image/*" />
                 </div>
                 <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase">{user?.username}</h3>
                    <p className="text-[10px] font-bold text-indigo-600 uppercase tracking-[0.2em] mt-1">Practice Principal Account</p>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 block ml-1">Legal Firm Name</label><input required value={profileData.firm_name} onChange={e => setProfileData({...profileData, firm_name: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold uppercase outline-none focus:ring-4 focus:ring-indigo-50" /></div>
                 <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 block ml-1">Firm GSTN</label><input value={profileData.gstn} onChange={e => setProfileData({...profileData, gstn: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold uppercase outline-none font-mono" /></div>
                 <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 block ml-1">Work Email</label><input required value={profileData.email_id} onChange={e => setProfileData({...profileData, email_id: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none" /></div>
                 <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 block ml-1">Mobile No</label><input value={profileData.mobile_no} onChange={e => setProfileData({...profileData, mobile_no: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none" /></div>
              </div>
              <button type="submit" disabled={isLoading} className="bg-indigo-600 text-white font-black uppercase tracking-widest px-10 py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all text-[10px]">{isLoading ? 'Syncing...' : 'Save Firm Profile'}</button>
           </form>
         )}

         {activeTab === 'security' && (
           <form onSubmit={handleSecuritySave} className="space-y-10 animate-in slide-in-from-bottom-4 duration-300">
              <div className="space-y-6">
                 <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 block ml-1">Master User ID</label><input required value={securityData.user_id} onChange={e => setSecurityData({...securityData, user_id: e.target.value.toUpperCase()})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-black uppercase outline-none focus:ring-4 focus:ring-indigo-50" /></div>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 block ml-1">New Password</label><input type="password" value={securityData.newPassword} onChange={e => setSecurityData({...securityData, newPassword: e.target.value})} placeholder="••••••••" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-50" /></div>
                    <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 block ml-1">Confirm Password</label><input type="password" value={securityData.confirmPassword} onChange={e => setSecurityData({...securityData, confirmPassword: e.target.value})} placeholder="••••••••" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-50" /></div>
                 </div>
              </div>
              <button type="submit" disabled={isLoading} className="bg-slate-900 text-white font-black uppercase tracking-widest px-10 py-4 rounded-xl shadow-xl hover:bg-indigo-600 transition-all text-[10px]">Rotate Access Keys</button>
           </form>
         )}

         {activeTab === 'appearance' && (
           <div className="space-y-12 animate-in slide-in-from-bottom-4 duration-300">
              <section>
                 <h4 className="text-[10px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6">Visual Scaling</h4>
                 <div className="grid grid-cols-3 gap-4">
                    {[{ l: 'Compact', v: 14 }, { l: 'Default', v: 16 }, { l: 'Large', v: 18 }].map(sz => (
                      <button key={sz.v} onClick={() => applyUiSettings({...uiSettings, fontSize: sz.v})} className={`flex flex-col items-center p-6 rounded-2xl border-2 transition-all ${uiSettings.fontSize === sz.v ? 'bg-indigo-50 border-indigo-600' : 'bg-slate-50 border-slate-100 text-slate-400'}`}>
                        <span className="text-[10px] font-black uppercase tracking-widest mb-2">{sz.l}</span>
                        <span className="font-black" style={{ fontSize: sz.v + 'px' }}>Aa</span>
                      </button>
                    ))}
                 </div>
              </section>
              <section>
                 <h4 className="text-[10px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6">Typography Style</h4>
                 <div className="grid grid-cols-3 gap-4">
                    {[{ l: 'Modern Sans', v: 'sans' }, { l: 'Classic Serif', v: 'serif' }, { l: 'Statutory Mono', v: 'mono' }].map(sty => (
                      <button key={sty.v} onClick={() => applyUiSettings({...uiSettings, fontStyle: sty.v})} className={`flex flex-col items-center p-6 rounded-2xl border-2 transition-all ${uiSettings.fontStyle === sty.v ? 'bg-indigo-50 border-indigo-600' : 'bg-slate-50 border-slate-100 text-slate-400'} app-font-${sty.v}`}>
                        <span className="text-[10px] font-black uppercase tracking-widest mb-2">{sty.l}</span>
                        <span className="text-xl font-black">Ref</span>
                      </button>
                    ))}
                 </div>
              </section>
           </div>
         )}

         {activeTab === 'data' && (
           <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-300">
              <div className="p-8 bg-slate-50 rounded-3xl border border-slate-100">
                 <h4 className="text-sm font-black text-slate-900 uppercase mb-2">Vault Snapshot</h4>
                 <p className="text-xs text-slate-500 mb-6">Download an encrypted JSON export of all client records and litigation history.</p>
                 <button onClick={triggerBackup} className="w-full bg-white border-2 border-indigo-600 text-indigo-600 font-black uppercase tracking-widest py-4 rounded-xl hover:bg-indigo-600 hover:text-white transition-all text-[10px]">Download Master Snapshot</button>
              </div>
              <div className="p-8 bg-slate-900 rounded-3xl text-white">
                 <h4 className="text-sm font-black uppercase mb-2">Restore Archive</h4>
                 <p className="text-xs text-slate-400 mb-6">Upload a previously saved vault file to restore practice data.</p>
                 <button onClick={() => restoreInputRef.current?.click()} className="w-full bg-indigo-600 text-white font-black uppercase tracking-widest py-4 rounded-xl hover:bg-white hover:text-slate-900 transition-all text-[10px]">Select Restore File</button>
                 <input type="file" ref={restoreInputRef} onChange={handleRestore} className="hidden" accept=".json" />
              </div>
           </div>
         )}
      </div>
    </div>
  );
};

export default Setting;
